chrome/browser/ui/views/frame/browser_fr.BrowserLayoutParams BrowserFrameViewWin::
BrowserLayoutParams BrowserFrameViewWin::GetBrowserLayoutParams() const {
  BrowserLayoutParams params;
  params.visual_client_area = client_view_bounds_;
  const int top = params.visual_client_area.y();
  const auto& caption = caption_button_container_->bounds();
  // In some cases, the top of the client area is moved down, but slightly
  // overlaps the bottom of the caption container. In that case, don't count
  // the caption buttons in the exclusion area.
  if (top < caption.bottom() - 2) {
    if (CaptionButtonsOnLeadingEdge()) {
      params.leading_exclusion.content =
          gfx::SizeF(caption.right(), caption.bottom() - top);
    } else {
      params.trailing_exclusion.content =
          gfx::SizeF(width() - caption.x(), caption.bottom() - top);
      // In overlay mode, the icon is present but hidden.
      if (window_icon_ && !GetBrowserView()->IsWindowControlsOverlayEnabled()) {
        const auto& icon = window_icon_->bounds();
        params.leading_exclusion.content =
            gfx::SizeF(icon.right(), icon.bottom() - top);
        params.leading_exclusion.horizontal_padding = kIconTitleSpacing;
        params.leading_exclusion.vertical_padding = icon.y() - top;
      }
    }
  }
  return params;
}

chrome/browser/ui/views/frame/browser_fr.void BrowserFrameViewWin::LayoutCaptionB:
void BrowserFrameViewWin::LayoutCaptionButtons() {
  TRACE_EVENT0("views.frame", "BrowserFrameViewWin::LayoutCaptionButtons");

  const bool hide_window_buttons =
      base::CommandLine::ForCurrentProcess()->HasSwitch("hide-window-buttons");
  caption_button_container_->SetVisible(
      !hide_window_buttons &&
      (!browser_widget()->IsFullscreen() ||
       GetBrowserView()->IsWindowControlsOverlayEnabled()));

  const gfx::Size preferred_size =
      hide_window_buttons ? gfx::Size()
                          : caption_button_container_->GetPreferredSize();

  const int height =
      !GetBrowserView()->GetWebAppFrameToolbarPreferredSize().IsEmpty()
          ? (TitlebarHeight(false) - WindowTopY())
          : GetFrameHeight();

  const int x = CaptionButtonsOnLeadingEdge()
                    ? (hide_window_buttons ? 0 : 8)
                    : width() - preferred_size.width();
  caption_button_container_->SetBounds(x, WindowTopY(), preferred_size.width(),
                                       height);
}

chrome/browser/ui/views/frame/browser_fr.int BrowserFrameViewWin::NonClientHitTes:
int BrowserFrameViewWin::NonClientHitTest(const gfx::Point& point) {
  int super_component = BrowserFrameView::NonClientHitTest(point);
  if (super_component != HTNOWHERE) {
    return super_component;
  }

  // If the point isn't within our bounds, then it's in the native portion of
  // the frame so again Windows can figure it out.
  if (!bounds().Contains(point)) {
    return HTNOWHERE;
  }

  // At the window corners the resize area is not actually bigger, but the 16
  // pixels at the end of the top and bottom edges trigger diagonal resizing.
  constexpr int kResizeCornerWidth = 16;

  const int top_border_thickness =
      (GetBrowserView()->GetIsWebAppType() || IsFrameCondensed())
          ? FrameTopBorderThickness(false)
          : GetLayoutConstant(LayoutConstant::kTabStripPadding);

  const int window_component = GetHTComponentForFrame(
      point, gfx::Insets::TLBR(top_border_thickness, 0, 0, 0),
      top_border_thickness, kResizeCornerWidth - FrameBorderThickness(),
      browser_widget()->widget_delegate()->CanResize());

  const int frame_component =
      browser_widget()->client_view()->NonClientHitTest(point);

  // Leading controls can overlap the client view's sidebar/toolbar bounds.
  // Resolve their existing native hit codes before the client claims them.
  if (CaptionButtonsOnLeadingEdge() &&
      caption_button_container_->GetVisible()) {
    const gfx::Point local =
        ConvertPointToTarget(parent(), caption_button_container_, point);
    if (caption_button_container_->HitTestPoint(local)) {
      const int hit = caption_button_container_->NonClientHitTest(local);
      if (hit == HTMINBUTTON || hit == HTMAXBUTTON || hit == HTCLOSE) {
        if (!IsMaximized() && window_component >= HTLEFT &&
            window_component <= HTBOTTOMRIGHT) {
          return window_component;
        }
        return hit;
      }
    }
  }

  // In fullscreen there is no draggable or resizable frame, so window
  // controls overlay hits outside the caption buttons must stay HTCLIENT;
  // HTCAPTION would swallow clicks meant for the overlaid app UI.
  const bool is_fullscreen_with_overlay =
      browser_widget()->IsFullscreen() &&
      GetBrowserView()->IsWindowControlsOverlayEnabled();

  // See if we're in the sysmenu region.  We still have to check the tabstrip
  // first so that clicks in a tab don't get treated as sysmenu clicks.
  if (frame_component != HTCLIENT && ShouldShowWindowIcon(TitlebarType::kAny)) {
    gfx::Rect sys_menu_region(
        0, display::win::GetScreenWin()->GetSystemMetricsInDIP(SM_CYSIZEFRAME),
        display::win::GetScreenWin()->GetSystemMetricsInDIP(SM_CXSMICON),
        display::win::GetScreenWin()->GetSystemMetricsInDIP(SM_CYSMICON));
    if (sys_menu_region.Contains(point)) {
      return HTSYSMENU;
    }
  }

  if (frame_component != HTNOWHERE) {
    if (is_fullscreen_with_overlay) {
      return HTCLIENT;
    }

    // If the clientview registers a hit within its bounds, it's still possible
    // that the hit target should be top resize since the tabstrip region paints
    // to the top of the frame. If the frame registered a hit for the Top
    // resize, override the client frame target.
    if (window_component == HTTOP && !IsMaximized()) {
      return window_component;
    }
    return frame_component;
  }

  // Then see if the point is within any of the window controls.
  const gfx::Point local_point =
      ConvertPointToTarget(parent(), caption_button_container_, point);
  if (caption_button_container_->HitTestPoint(local_point)) {
    const int hit_test_result =
        caption_button_container_->NonClientHitTest(local_point);
    if (hit_test_result != HTNOWHERE) {
      return hit_test_result;
    }
  }

  if (is_fullscreen_with_overlay) {
    return HTCLIENT;
  }

  // On Windows, the caption buttons are almost butted up to the top right
  // corner of the window. This code ensures the mouse isn't set to a size
  // cursor while hovering over the caption buttons, thus giving the incorrect
  // impression that the user can resize the window.
  RECT button_bounds = {0};
  if (!CaptionButtonsOnLeadingEdge() &&
      SUCCEEDED(DwmGetWindowAttribute(views::HWNDForWidget(browser_widget()),
                                      DWMWA_CAPTION_BUTTON_BOUNDS,
                                      &button_bounds, sizeof(button_bounds)))) {
    gfx::RectF button_bounds_in_dips = gfx::ConvertRectToDips(
        gfx::Rect(button_bounds), display::win::GetDPIScale());
    // TODO(crbug.com/40150311): GetMirroredRect() requires an integer rect,
    // but the size in DIPs may not be an integer with a fractional device
    // scale factor. If we want to keep using integers, the choice to use
    // ToFlooredRectDeprecated() seems to be doing the wrong thing given the
    // comment below about insetting 1 DIP instead of 1 physical pixel. We
    // should probably use ToEnclosedRect() and then we could have inset 1
    // physical pixel here.
    gfx::Rect buttons =
        GetMirroredRect(gfx::ToFlooredRectDeprecated(button_bounds_in_dips));

    // There is a small one-pixel strip right above the caption buttons in
    // which the resize border "peeks" through.
    constexpr int kCaptionButtonTopInset = 1;
    // The sizing region at the window edge above the caption buttons is
    // 1 px regardless of scale factor. If we inset by 1 before converting
    // to DIPs, the precision loss might eliminate this region entirely. The
    // best we can do is to inset after conversion. This guarantees we'll
    // show the resize cursor when resizing is possible. The cost of which
    // is also maybe showing it over the portion of the DIP that isn't the
    // outermost pixel.
    buttons.Inset(gfx::Insets::TLBR(kCaptionButtonTopInset, 0, 0, 0));
    if (buttons.Contains(point)) {
      return HTNOWHERE;
    }
  }

  // Fall back to the caption if no other component matches.
  return (window_component == HTNOWHERE) ? HTCAPTION : window_component;
}

chrome/browser/ui/views/frame/windows_ca.void WindowsCaptionButton::PaintMacSymbo:
void WindowsCaptionButton::PaintMacSymbol(gfx::Canvas* canvas) {
  SkColor color;
  switch (button_type_) {
    case VIEW_ID_CLOSE_BUTTON:
      color = SkColorSetRGB(255, 95, 87);
      break;
    case VIEW_ID_MINIMIZE_BUTTON:
      color = SkColorSetRGB(254, 188, 46);
      break;
    case VIEW_ID_MAXIMIZE_BUTTON:
    case VIEW_ID_RESTORE_BUTTON:
      color = SkColorSetRGB(40, 200, 64);
      break;
    default:
      NOTREACHED();
  }
  if (!GetEnabled() || !GetWidget()->ShouldPaintAsActive()) {
    color = SkColorSetRGB(150, 150, 150);
  } else if (GetState() == STATE_PRESSED) {
    color =
        color_utils::GetResultingPaintColor(SkColorSetARGB(45, 0, 0, 0), color);
  }

  const auto middle = GetContentsBounds().CenterPoint();
  const gfx::PointF center(middle.x(), middle.y());
  cc::PaintFlags flags;
  flags.setAntiAlias(true);
  flags.setColor(color);
  canvas->DrawCircle(center, 6.f, flags);
  flags.setColor(SkColorSetARGB(56, 0, 0, 0));
  flags.setStyle(cc::PaintFlags::kStroke_Style);
  flags.setStrokeWidth(0.5f);
  canvas->DrawCircle(center, 5.75f, flags);

  if (!GetEnabled() ||
      (GetState() != STATE_HOVERED && GetState() != STATE_PRESSED)) {
    return;
  }
  flags.setColor(SkColorSetARGB(190, 0, 0, 0));
  flags.setStrokeWidth(1.f);
  const float x = center.x();
  const float y = center.y();
  if (button_type_ == VIEW_ID_CLOSE_BUTTON) {
    canvas->DrawLine(gfx::PointF(x - 2.5f, y - 2.5f),
                     gfx::PointF(x + 2.5f, y + 2.5f), flags);
    canvas->DrawLine(gfx::PointF(x - 2.5f, y + 2.5f),
                     gfx::PointF(x + 2.5f, y - 2.5f), flags);
  } else if (button_type_ == VIEW_ID_RESTORE_BUTTON) {
    canvas->DrawRect(gfx::RectF(x - 2.5f, y - 2.f, 5.f, 4.f), flags);
  } else {
    canvas->DrawLine(gfx::PointF(x - 3.f, y), gfx::PointF(x + 3.f, y), flags);
    if (button_type_ == VIEW_ID_MAXIMIZE_BUTTON) {
      canvas->DrawLine(gfx::PointF(x, y - 3.f), gfx::PointF(x, y + 3.f), flags);
    }
  }
}

chrome/browser/ui/views/frame/windows_ca.void WindowsCaptionButton::PaintButtonCo:
void WindowsCaptionButton::PaintButtonContents(gfx::Canvas* canvas) {
  if (frame_view_->CaptionButtonsOnLeadingEdge()) {
    PaintMacSymbol(canvas);
    return;
  }
  PaintSymbol(canvas);
}

chrome/browser/ui/views/frame/windows_ca.gfx::Size WindowsCaptionButton::Calculat:
gfx::Size WindowsCaptionButton::CalculatePreferredSize(
    const views::SizeBounds& available_size) const {
  const int width = frame_view_->CaptionButtonsOnLeadingEdge()
                        ? 22
                        : WindowFrameUtil::kWindowsCaptionButtonWidth +
                              GetBetweenButtonSpacing();

  // TODO(bsep): The sizes in this function are for 1x device scale and don't
  // match Windows button sizes at hidpi.
  int height = WindowFrameUtil::kWindowsCaptionButtonHeightRestored;
  if (frame_view_->IsMaximized()) {
    const auto info = frame_view_->GetBrowserView()->GetFrameElementInfo();
    int maximized_height = info.tabstrip_preferred_height
                               ? info.tabstrip_preferred_height
                               : frame_view_->TitlebarMaximizedVisualHeight();
    constexpr int kMaximizedBottomMargin = 2;
    maximized_height -= kMaximizedBottomMargin;
    height = std::min(height, maximized_height);
  }
  return gfx::Size(width, height);
}

chrome/browser/ui/views/frame/windows_ca.int WindowsCaptionButton::GetBetweenButt:
int WindowsCaptionButton::GetBetweenButtonSpacing() const {
  if (frame_view_->CaptionButtonsOnLeadingEdge()) {
    return 0;
  }
  const int display_order_index = GetButtonDisplayOrderIndex();
  return display_order_index == 0
             ? 0
             : WindowFrameUtil::kWindowsCaptionButtonVisualSpacing;
}

chrome/browser/ui/views/frame/browser_ca.void BrowserCaptionButtonContainer::Upda:
void BrowserCaptionButtonContainer::UpdateMacButtonStyle() {
  const bool mac_style = frame_view_->CaptionButtonsOnLeadingEdge();
  if (mac_style_ == mac_style) {
    return;
  }
  mac_style_ = mac_style;
  if (mac_style) {
    ReorderChildView(close_button_, 0);
    ReorderChildView(minimize_button_, 1);
    ReorderChildView(maximize_button_, 2);
    ReorderChildView(restore_button_, 3);
  } else {
    ReorderChildView(minimize_button_, 0);
    ReorderChildView(maximize_button_, 1);
    ReorderChildView(restore_button_, 2);
    ReorderChildView(close_button_, 3);
  }
  for (auto* button : {close_button_.get(), minimize_button_.get(),
                       maximize_button_.get(), restore_button_.get()}) {
    button->PreferredSizeChanged();
  }
  InvalidateLayout();
}

void BrowserCaptionButtonContainer::UpdateButtons() {
  UpdateMacButtonStyle();
  minimize_button_->SetVisible(frame_view_->GetBrowserView()->CanMinimize());

  const bool is_maximized = frame_view_->IsMaximized();
  const bool can_maximize = frame_view_->GetBrowserView()->CanMaximize();
  restore_button_->SetVisible(is_maximized && can_maximize);
  maximize_button_->SetVisible(!is_maximized && can_maximize);

  close_button_->SetVisible(true);

  // In touch mode, windows cannot be taken out of fullscreen or tiled mode, so
  // the maximize/restore button should be disabled, unless the window is not
  // maximized. TODO(crbug.com/40849150): Also check if the window is tiled.
  const bool is_touch = ui::TouchUiController::Get()->touch_ui();
  restore_button_->SetEnabled(!is_touch);
  maximize_button_->SetEnabled(!is_touch || !is_maximized);
}

chrome/browser/ui/views/frame/browser_ca.int BrowserCaptionButtonContainer::NonCl:
int BrowserCaptionButtonContainer::NonClientHitTest(
    const gfx::Point& point) const {
  DCHECK(HitTestPoint(point))
      << "should only be called with a point inside this view's bounds";

  // | WCO | Win11 | Caption Button    | Output                |
  // |-----+-------+-------------------+-----------------------|
  // | No  | -     | All               | Original mapped value |
  // | Yes | No    | All               | HTCLIENT              |
  // | Yes | Yes   | Minimize, Close   | HTCLIENT              |
  // | Yes | Yes   | Maximize, Restore | HTMAXBUTTON           |

  // For views without Window Controls Overlay (WCO) enabled, the original hit
  // test result is returned as-is.

  // BrowserView covers the frame view when Window Controls Overlay is enabled.
  // The native window that encompasses Web Contents gets the mouse events meant
  // for the caption buttons, so returning HTCLIENT allows these buttons to be
  // highlighted on hover. However, on Windows 11 the maximize and restore
  // buttons must return HTMAXBUTTON so that Windows can show the Snap Layouts
  // popup when the user hovers over the maximize/restore button.

  int hit_test_result = HTCAPTION;
  if (HitTestCaptionButton(minimize_button_, point)) {
    hit_test_result = HTMINBUTTON;
  } else if (HitTestCaptionButton(maximize_button_, point) ||
             HitTestCaptionButton(restore_button_, point)) {
    hit_test_result = HTMAXBUTTON;
  } else if (HitTestCaptionButton(close_button_, point)) {
    hit_test_result = HTCLOSE;
  }

  // Return the base component if no button was hit or WCO is disabled.
  if (hit_test_result == HTCAPTION ||
      !frame_view_->GetBrowserView()->IsWindowControlsOverlayEnabled()) {
    return hit_test_result;
  }

  const bool is_win11_maximize =
      (hit_test_result == HTMAXBUTTON) &&
      (base::win::GetVersion() >= base::win::Version::WIN11);

  return is_win11_maximize ? HTMAXBUTTON : HTCLIENT;
}
